const e={id:"indistractable",title:"Indistractable",author:"Nir Eyal",courseIds:["focus","procrastination"],sources:[{id:"indistractable-identification",title:"Indistractable author description",url:"https://www.nirandfar.com/indistractable",citation:"Eyal, N. Indistractable. Official author book page, accessed 2026-10-08.",kind:"book-identification",population:"Author/developer description, no empirical sample.",finding:"Identifies the book and themes only.",limitation:"Promotional practitioner material; not evidence for efficacy.",checkedOn:"2026-10-08"},{id:"mood-repair",title:"Procrastination and short-term mood regulation",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",citation:"Sirois, F. M., & Pychyl, T. A. (2013). Procrastination and the priority of short-term mood regulation: Consequences for future self. Social and Personality Psychology Compass, 7(2), 115–127. DOI: 10.1111/spc3.12011.",kind:"review",population:"Theoretical narrative review, no new sample or pooled effect.",finding:"Avoidance of unpleasant task feelings is a useful account of some procrastination.",limitation:"Not a universal cause of distraction or proof that naming feelings alone changes behavior; older resource claims are not imported.",checkedOn:"2026-10-08",dossier:"procrastination.md P02; VERIFY.md interpretation limits"},{id:"phone-notifications",title:"Silence your phones",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",citation:"Kushlev, K., Proulx, J., & Dunn, E. W. (2016). Silence your phones: Smartphone notifications increase inattention and hyperactivity symptoms. CHI 2016, 1011–1020. DOI: 10.1145/2858036.2858359.",kind:"trial",population:"Counterbalanced two-week experiment, 221 university students, paired symptom tests in 190.",finding:"Low interruption setup yielded lower self-reported inattention and hyperactivity symptoms.",limitation:"Visibility/reach and alerts changed together; unblinded self-report, no isolated notification effect or ADHD treatment claim.",checkedOn:"2026-10-08",dossier:"focus.md F06"},{id:"if-then-plans",title:"Implementation intentions and goal achievement",url:"https://www.researchgate.net/profile/Peter-Gollwitzer-2/publication/37367696_Implementation_Intentions_and_Goal_Achievement_A_Meta-Analysis_of_Effects_and_Processes/links/59d91a24a6fdcc2aad0d8c1f/Implementation-Intentions-and-Goal-Achievement-A-Meta-Analysis-of-Effects-and-Processes.pdf",citation:"Gollwitzer, P. M., & Sheeran, P. (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology, 38, 69–119. DOI: 10.1016/S0065-2601(06)38002-1.",kind:"meta-analysis",population:"94 tests, 8,461 participants; diverse laboratory and field goals, predominantly student samples.",finding:"Specific cue-response plans improved goal attainment on average, d = 0.65, 95% CI 0.60–0.70.",limitation:"Older synthesis includes 83 experimental and 11 correlational tests; not proof of GTD, time blocking, an ODA action, or a two-minute dose.",checkedOn:"2026-10-08",dossier:"turning-day.md T03; focus.md F04; procrastination.md P03; VERIFY.md design correction"},{id:"obstacle-planning",title:"Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",citation:"Wang, G., Wang, Y., & Gai, X. (2021). A meta-analysis of the effects of mental contrasting with implementation intentions on goal attainment. Frontiers in Psychology, 12, 565202. DOI: 10.3389/fpsyg.2021.565202.",kind:"meta-analysis",population:"21 articles, 24 independent effects, 15,907 participants; varied ages and goal domains.",finding:"Modest average goal-attainment benefit, g = 0.336, 95% CI 0.229–0.443.",limitation:"Heterogeneity and publication-bias indications; two large online samples dominate participant count; no guarantee or proof of every commitment format.",checkedOn:"2026-10-08",dossier:"turning-day.md T04; focus.md F05; procrastination.md P04; VERIFY.md sample correction"},{id:"progress-monitoring",title:"Does monitoring goal progress promote goal attainment?",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",citation:"Harkin, B., Webb, T. L., Chang, B. P. I., Prestwich, A., Conner, M., Kellar, I., Benn, Y., & Sheeran, P. (2016). Does monitoring goal progress promote goal attainment? A meta-analysis of the experimental evidence. Psychological Bulletin, 142(2), 198–229. DOI: 10.1037/bul0000025.",kind:"meta-analysis",population:"138 randomized studies, 19,951 participants with varied goals.",finding:"Goal attainment improved on average, d = 0.40, 95% CI 0.32–0.48 in opened abstract.",limitation:"Protocols varied; recording/reporting moderators do not validate a particular tracker, streak rule or review schedule.",checkedOn:"2026-10-08",dossier:"turning-day.md T05; focus.md F03; procrastination.md P13"}],locales:{en:{hook:"You opened your phone before the difficult sentence. Notice the moment, then choose a response.",intro:"Eyal’s book asks readers to look at the conditions surrounding distraction, including uncomfortable feelings, incoming prompts and how they allocate their time. ODA checks these themes independently rather than treating a compelling explanation as proof of an entire method. A useful action can address one interruption or one moment of avoidance without requiring perfect attention. Your phone may also be an accessibility aid, a family contact or part of your work, so the aim is a workable choice about use. Start with a recurring situation you can change safely and with information you can observe yourself.",ideas:[{id:"notice-discomfort",title:"Ask what the interruption offered you",idea:"Eyal encourages readers to examine the uncomfortable feeling that can precede a shift away from intended work. When you reach for something else, ask whether you were bored, uncertain, anxious or facing an unclear task, while leaving room for ordinary fatigue and legitimate competing demands. You can acknowledge the feeling and choose one feasible response without requiring yourself to feel good first or treating every pause as avoidance. If the task is unsafe or the demand unreasonable, the appropriate response may be rest, help or renegotiation rather than returning to it at any cost.",research:"Sirois and Pychyl review procrastination as a way of seeking short-term relief from unpleasant task feelings. This is a useful explanatory account for some delay, but the source is a theoretical narrative review rather than a trial establishing a universal cause of distraction. It does not show that naming a feeling alone changes behavior or that all external barriers can be handled internally. The verdict is mixed for this broad explanation. Use the question to identify a possible barrier, then check what kind of response is needed instead of deciding in advance that every lapse has the same emotional mechanism.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Change the prompts that repeatedly pull you away",idea:"The book recommends taking a deliberate look at the external prompts that compete with intended action, including the way devices ask for attention. Select one avoidable prompt and decide when you want to meet it, rather than stripping away every contact channel or promising never to use your phone. An ODA adaptation is to mute a nonessential group for one planned task and choose a later time to check it, while leaving urgent contacts available. If your role requires rapid responses, discuss a feasible protected period with the people affected instead of assuming that every interruption is under your control.",research:"In a counterbalanced experiment involving 221 university students, a low-interruption phone setup accompanied lower self-reported inattention and hyperactivity symptoms than a high-interruption setup. Alerts and the phone’s visibility or reach changed together, so the study cannot isolate notification silencing as the cause. It also does not show that phones cause ADHD, treat a clinical condition or guarantee higher productivity. The verdict is mixed for a specific settings change, with promising evidence for the broader setup. Test one safe adjustment and judge the observable effect on your chosen task, rather than treating all device use as equally harmful.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Choose the action before the difficult moment",idea:"Eyal favors deliberate planning so that the intended use of a period is clear when alternatives appear. Identify one task you genuinely want to pursue, the likely moment of diversion and a response that is possible in that situation, including a smaller action or a request for missing information. For an ODA adaptation, if you notice an urge to check messages during a chosen writing start, first write the unresolved question in the document, then reconsider the check at your planned time. The plan should guide a choice, not become a rigid rule that prevents you from responding to a real emergency.",research:"Cue-response plans have support from Gollwitzer and Sheeran’s meta-analysis, and a later synthesis found a modest average benefit from pairing obstacle identification with implementation intentions. The studies concerned varied goals and did not test every time-allocation rule from this book. Heterogeneity and publication-bias signals limit the size of benefit you should expect from the later review, and a brief ODA sentence has not been validated as a complete intervention. The supported principle is preparing a feasible response to a recognizable situation. Include real external constraints when choosing it, and judge success by the actual attempt rather than the intention alone.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Make commitment observable without making it punitive",idea:"The book uses advance commitments to help readers protect intentions, but a personal commitment should remain safe and proportionate to the task. Choose a private record or an optional check-in that tells you whether you attempted the action, without spending money, exposing sensitive details or creating a punishment for unavoidable interruptions. If the commitment starts producing concealment or self-criticism, change the design and ask what barrier the original promise ignored. A commitment is useful only when it helps you make or review a decision; announcing a plan does not prove that you followed it or that it still fits.",research:"Progress-monitoring interventions improved goal attainment on average in 138 randomized studies reviewed by Harkin and colleagues. Effects were larger alongside physical recording or reporting, but those moderator findings do not establish that a particular promise, pact or public announcement causes the improvement. The obstacle-planning evidence also concerns varied intervention packages rather than validating every commitment format. The verdict is mixed for using a specific pact, with stronger support for accurate monitoring. Keep disclosure voluntary and the record honest, and treat a missed attempt as a reason to revise the feasible response instead of escalating the cost of failure.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"Plan for one distraction in two minutes",steps:["Name one task for today and the recurring, nonurgent distraction that tends to interrupt it.","Write one feasible if-then response and choose when you will check the distraction instead.","Make one safe adjustment to the prompt, keeping urgent and accessibility contacts available."],decision:"Today I will write one response to a familiar distraction and make one safe adjustment to its prompt."},takeaway:"Keep the specific response plan. Treat emotional explanations, device settings and commitment formats with their limits in view, because evidence for some mechanisms does not prove a complete distraction-proof method. Today’s two-minute plan is an ODA adaptation, not a tested dose or a treatment for attention difficulties. You can make one better-informed choice and still have a difficult day. If persistent problems substantially impair your life, seek qualified support while continuing the ordinary experiments that are safe and useful for you."},tr:{hook:"Zor cümleyi yazmadan telefonu açtın. O anı fark et, sonra karşılığını seç.",intro:"Eyal, dikkat dağılmasını çevreleyen koşullara bakmanı istiyor; rahatsız duygular, dışarıdan gelen işaretler ve zamanını nasıl ayırdığın buna dahil. ODA bu fikirleri tek tek kontrol ediyor, çünkü ikna edici bir açıklama bütün yöntemin kanıtı değil. İşe yarar tek bir eylem, kusursuz dikkat gerektirmeden bir kesintiye veya kaçınma anına cevap verebilir. Telefonun erişilebilirlik yardımcısı, aile iletişimi veya işinin parçası da olabilir; amaç kullanım hakkında uygulanabilir bir seçim yapmak. Güvenle değiştirebileceğin tekrar eden bir durumla ve kendin gözleyebileceğin bilgiyle başla. Bir günün zorluğunu, bütün telefon alışkanlıkların veya kişiliğin hakkında genel hükme dönüştürmeden incele.",ideas:[{id:"notice-discomfort",title:"Kesintinin sana ne sunduğunu sor",idea:"Eyal, yapmak istediğin işten başka bir şeye geçmeden önce ortaya çıkabilen rahatsızlığı incelemeyi öneriyor. Başka bir şeye uzandığında sıkılmış, kararsız, kaygılı veya görev konusunda belirsizlik içinde olup olmadığına bak; sıradan yorgunluğa ve geçerli başka taleplere de yer bırak. Duyguyu kabul edip uygun bir karşılık seçebilirsin; önce iyi hissetmen gerekmiyor ve her arayı kaçınma saymak zorunda değilsin. Görev güvensiz ya da talep ölçüsüzse uygun karşılık, ne pahasına olursa olsun işe dönmek yerine dinlenmek, yardım istemek veya sorumluluğu yeniden görüşmek olabilir; hangi engelle karşılaştığını gerçekten anlamadan tek bir açıklamayı seçme.",research:"Sirois ve Pychyl, ertelemeyi hoş olmayan görev duygularından kısa süreli rahatlama aramanın bir yolu olarak ele alıyor. Bazı gecikmeler için yararlı bir açıklama bu, ama kaynak dikkat dağılmasının evrensel nedenini belirleyen bir deney değil, kuramsal bir anlatı derlemesi. Duyguyu adlandırmanın tek başına davranışı değiştirdiğini veya bütün dış engellerin içeriden yönetilebileceğini göstermiyor. Geniş açıklama için sonuç karışık. Soruyu olası bir engeli belirlemek için kullan, sonra ne tür bir karşılık gerektiğine bak. Her kopuşun aynı duygusal mekanizmadan kaynaklandığına baştan karar verme; görevin belirsizliği, gerçek kaynak eksikliği ve rahatsızlığı farklı biçimde ele almak gerekebilir, bu yüzden notunu bir tanı gibi kullanma.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Seni tekrar tekrar çeken işareti değiştir",idea:"Kitap, amaçlanan eylemle yarışan dış işaretleri, cihazların dikkat isteme biçimleri dahil, bilinçli biçimde incelemeyi öneriyor. Önlenebilir tek bir işaret seç ve onunla ne zaman karşılaşmak istediğini belirle; bütün iletişim kanallarını kaldırman veya telefonunu hiç kullanmayacağına söz vermen gerekmiyor. ODA uyarlaması olarak, planladığın tek bir iş sırasında zorunlu olmayan grubu sessize alıp daha sonra bakacağın zamanı seçebilir, acil kişileri açık bırakabilirsin. Görevin hızlı yanıt gerektiriyorsa bütün kesintilerin kontrolünde olduğunu varsaymak yerine, etkilenen kişilerle uygun bir korunan zaman konuş; bunun için işin gerçek beklentilerini bilmen gerekebilir.",research:"221 üniversite öğrencisinin katıldığı, sırası dengelenmiş bir deneyde, daha az kesintili telefon düzeni daha çok kesintili düzene göre daha düşük öz bildirimli dikkatsizlik ve hiperaktivite belirtileriyle birlikteydi. Bildirimler ile telefonun görünürlüğü veya ulaşılabilirliği birlikte değişti; bu yüzden çalışma, nedenin yalnızca bildirimleri kapatmak olduğunu ayıramıyor. Telefonların DEHB’ye neden olduğunu, klinik durumu tedavi ettiğini veya daha yüksek verimlilik garantilediğini de göstermiyor. Belirli bir ayar değişikliği için sonuç karışık, daha geniş düzen için umut veren bulgu var. Güvenli tek bir ayarlamayı dene ve seçtiğin işte gözlenebilir sonuca bak. Bütün cihaz kullanımını aynı derecede zararlı sayma veya araştırmanın ölçmediği bir hayat sonucunu olmuş gibi kaydetme.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Zor an gelmeden karşılığını seç",idea:"Eyal, alternatifler belirdiğinde ayırdığın zamanı nasıl kullanmak istediğinin açık olması için bilinçli planlamayı savunuyor. Gerçekten yapmak istediğin tek bir iş, muhtemel kopuş anı ve o durumda mümkün bir karşılık seç; buna daha küçük eylem veya eksik bilgi istemek de dahil olabilir. ODA uyarlaması olarak, seçtiğin yazı başlangıcında mesaj kontrol etme isteğini fark edersen önce dosyaya cevaplanmamış soruyu yazıp kontrolü belirlediğin zamanda yeniden değerlendirebilirsin. Plan bir seçimi yönlendirsin; gerçek acile cevap vermeni engelleyen katı kurala dönüşmesin, çünkü yazdığın niyet o an ortaya çıkan bütün ihtiyaçlardan haberdar olamaz.",research:"Durumu bir karşılığa bağlayan planlar için Gollwitzer ve Sheeran’ın meta-analizinden destek var; sonraki bir derleme, engeli belirlemeyle uygulama niyetlerini birleştirmenin hedefe ulaşmaya mütevazı ortalama katkısını buldu. Çalışmalar farklı hedeflerle ilgiliydi ve bu kitaptaki her zaman ayırma kuralını sınamıyordu. Farklılıklar ve yayın yanlılığı işaretleri, sonraki derlemeden bekleyebileceğin faydanın büyüklüğünü sınırlıyor; kısa bir ODA cümlesi de bütün müdahale olarak doğrulanmış değil. Desteklenen ilke, fark edilebilir duruma uygulanabilir karşılık hazırlamak. Seçerken gerçek dış kısıtları dahil et, başarıyı sadece niyetle değil gerçek denemeyle değerlendir. Planın başkasının cevabına bağlıysa, sanki o cevabı kendin sağlayabilecekmişsin gibi yazma.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Taahhüdü görünür kıl, cezaya dönüştürme",idea:"Kitap, niyetlerini korumak için önceden verilen taahhütler kullanıyor; kişisel taahhüt güvenli ve işle orantılı kalmalı. Eylemi deneyip denemediğini gösterecek özel bir kayıt veya isteğe bağlı kontrol seç; para harcamak, hassas bilgileri açıklamak veya önlenemez kesintiler için ceza koymak gerekmiyor. Taahhüt gizlemeye veya öz eleştiriye yol açmaya başlarsa tasarımı değiştir ve ilk sözün hangi engeli dışarıda bıraktığını sor. Yalnızca karar vermene ya da kararını gözden geçirmene yardımcıysa işe yarar; bir planı ilan etmek onu uyguladığını veya hâlâ koşullarına uyduğunu kanıtlamaz, bu yüzden görünürlük ile doğruluğu aynı şey sayma.",research:"Harkin ve çalışma arkadaşlarının incelediği 138 rastgele atamalı çalışmada, ilerleme izleme müdahaleleri hedefe ulaşmayı ortalama olarak iyileştirdi. Fiziksel kayıt veya paylaşmayla etkiler daha büyüktü, fakat bu karşılaştırmalar belirli bir sözün, anlaşmanın veya kamuya duyurunun iyileşmeye neden olduğunu göstermiyor. Engel planlama bulguları da bütün taahhüt biçimlerini doğrulamak yerine farklı müdahale paketleriyle ilgili. Belirli anlaşma için sonuç karışık, doğru izleme için destek daha güçlü. Paylaşma isteğe bağlı, kayıt dürüst kalsın; kaçırılan denemeyi başarısızlığın bedelini artırmak yerine uygulanabilir karşılığı düzenleme nedeni olarak gör. Bir kaydı paylaşmak istemiyorsan, yalnızca kendin kullanman onu eksik ya da değersiz bir seçenek haline getirme.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"İki dakikada bir dikkat dağılmasına karşı plan yap",steps:["Bugün yapacağın tek bir işi ve onu kesen tanıdık, acil olmayan dikkat dağıtıcıyı adlandır.","Yapılabilir bir eğer-o zaman karşılığı yaz ve dikkat dağıtıcıya sonra ne zaman bakacağını seç.","İşarette güvenli tek bir düzenleme yap; acil ve erişilebilirlik iletişimini açık tut."],decision:"Bugün tanıdık bir dikkat dağıtıcı için karşılık yazıp işaretinde güvenli tek bir düzenleme yapacağım."},takeaway:"Belirli karşılık planını koru. Duygusal açıklamaları, cihaz ayarlarını ve taahhüt biçimlerini sınırlarıyla ele al; bazı mekanizmalara kanıt olması bütünüyle dikkat dağılmaz bir yöntemi kanıtlamıyor. Bugünkü iki dakikalık plan ODA uyarlaması; sınanmış doz veya dikkat güçlüklerinin tedavisi değil. Daha bilinçli tek bir seçim yapıp yine zor bir gün geçirebilirsin. Kalıcı sorunlar hayatını belirgin etkiliyorsa, güvenli ve yararlı gündelik denemelerine devam ederken yetkin destek ara. Denemenin sonucu, ihtiyacın olan yardımın önkoşulu olmasın; hangi durumda neyin işe yaradığını kaydetmek, bütün güçlüğü tek başına çözme sözü vermek değildir."},es:{hook:"Abriste el móvil antes de escribir la frase difícil. Observa ese momento y elige una respuesta.",intro:"Eyal invita a examinar las condiciones que rodean la distracción, incluidas las sensaciones incómodas, los avisos externos y la distribución del tiempo. ODA comprueba esas ideas por separado: una explicación convincente no prueba el método entero. Una acción útil puede atender una interrupción o un momento de evitación sin exigir atención perfecta. Tu móvil también puede ser una ayuda de accesibilidad, un contacto familiar o parte del trabajo; buscamos una elección viable sobre su uso. Empieza con una situación recurrente que puedas modificar con seguridad y con información observable, sin convertir un día difícil en un juicio general sobre tu disciplina.",ideas:[{id:"notice-discomfort",title:"Pregunta qué te ofrecía cambiar de actividad",idea:"Eyal propone investigar el malestar que puede aparecer antes de apartarte del trabajo previsto. Cuando buscas otra cosa, pregunta si estabas aburrido, inseguro, inquieto o ante una tarea poco clara, dejando sitio para el cansancio normal y otras demandas legítimas. Puedes reconocer la sensación y escoger una respuesta posible sin esperar a sentirte bien ni considerar toda pausa como evitación. Si la tarea es insegura o la exigencia desmedida, lo apropiado puede ser descansar, buscar ayuda o renegociar en lugar de volver a cualquier precio; necesitas identificar la barrera antes de atribuirle una causa única.",research:"Sirois y Pychyl analizan la procrastinación como búsqueda de alivio a corto plazo frente a sentimientos desagradables asociados con una tarea. Es una explicación útil para algunos retrasos, pero se trata de una revisión teórica narrativa, no de un ensayo que establezca una causa universal de distracción. No demuestra que nombrar una emoción cambie por sí solo la conducta ni que todas las barreras externas puedan resolverse desde dentro. El veredicto es mixto para la explicación amplia. Usa la pregunta para identificar un obstáculo posible y después averigua qué respuesta necesita, en vez de decidir que cada desvío sigue el mismo mecanismo emocional.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Modifica los avisos que te apartan una y otra vez",idea:"El libro recomienda examinar deliberadamente las señales externas que compiten con lo que quieres hacer, incluida la manera en que los dispositivos solicitan atención. Selecciona un aviso evitable y decide cuándo quieres atenderlo, sin eliminar todos los canales ni prometer no usar nunca el móvil. Como adaptación de ODA, puedes silenciar un grupo no esencial durante una tarea prevista y elegir otra hora para consultarlo, conservando contactos urgentes. Si necesitas responder rápido por trabajo, acuerda un período protegido viable con las personas afectadas, en vez de asumir que cada interrupción está bajo tu control.",research:"En un experimento con orden contrabalanceado y 221 estudiantes universitarios, una configuración con menos interrupciones se acompañó de menos síntomas autoinformados de inatención e hiperactividad. Cambiaron a la vez los avisos y la visibilidad o proximidad del teléfono, por lo que no puede aislarse el silenciamiento de notificaciones como causa. Tampoco demuestra que los móviles causen TDAH, que esta práctica trate una condición clínica ni que garantice productividad. El resultado es mixto para un ajuste específico, con evidencia prometedora para la configuración más amplia. Prueba un cambio seguro y evalúa el efecto observable sobre tu tarea, sin considerar todo uso del dispositivo igualmente perjudicial.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Elige la respuesta antes del momento difícil",idea:"Eyal favorece la planificación deliberada para que el uso deseado del tiempo esté claro cuando aparezcan alternativas. Identifica una tarea que de verdad quieras realizar, el momento probable del desvío y una respuesta posible, incluido un paso menor o pedir información que falta. Una adaptación de ODA es escribir primero la pregunta pendiente en el documento cuando surjan ganas de revisar mensajes durante el inicio previsto, y reconsiderar la consulta a la hora elegida. El plan debe orientar una elección, no convertirse en una norma rígida que te impida atender una emergencia real o un cambio sustancial de circunstancias.",research:"Los planes de señal y respuesta tienen apoyo en el metaanálisis de Gollwitzer y Sheeran; otra síntesis posterior encontró un beneficio medio modesto al combinar obstáculos e intenciones de implementación. Los estudios trataban objetivos variados y no comprobaron cada regla de organización temporal del libro. La heterogeneidad y las señales de sesgo de publicación limitan el beneficio esperado de la revisión posterior, y una frase breve de ODA no está validada como intervención completa. El principio respaldado es preparar una respuesta viable a una situación reconocible. Incluye restricciones externas reales y juzga por el intento, no solo por la intención; una respuesta ajena pendiente no está bajo tu control.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Haz observable el compromiso sin convertirlo en castigo",idea:"El libro usa compromisos anticipados para proteger intenciones, pero el compromiso personal debe ser seguro y proporcional a la tarea. Elige un registro privado o una comprobación opcional que muestre si intentaste la acción, sin gastar dinero, revelar detalles delicados ni castigar interrupciones inevitables. Si empieza a provocar ocultación o autocrítica, modifica el diseño y pregunta qué barrera ignoraba la promesa inicial. Un compromiso sirve si ayuda a decidir o revisar; anunciar un plan no demuestra que lo hayas seguido ni que todavía encaje con tu situación, así que no confundas visibilidad con exactitud.",research:"Las intervenciones de seguimiento mejoraron de media el logro de objetivos en los 138 estudios aleatorizados revisados por Harkin y sus colegas. Los efectos eran mayores con registro físico o comunicación, pero esos análisis no establecen que una promesa, pacto o anuncio concretos causen la mejoría. La evidencia sobre planificación de obstáculos también estudia paquetes diversos, no cualquier formato de compromiso. El veredicto es mixto para un pacto específico, con apoyo más firme para observar con precisión. Mantén la divulgación voluntaria y el registro sincero; un intento perdido invita a revisar una respuesta viable, no a aumentar el coste del fracaso.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"Prepara un plan para una distracción en dos minutos",steps:["Nombra una tarea de hoy y una distracción recurrente que no sea urgente.","Escribe una respuesta viable de si-entonces y una hora posterior para atender esa distracción.","Ajusta una señal de forma segura, manteniendo los contactos urgentes y de accesibilidad."],decision:"Hoy escribiré una respuesta para una distracción conocida y haré un ajuste seguro en la señal."},takeaway:"Conserva el plan específico de respuesta. Usa las explicaciones emocionales, los ajustes de dispositivos y los compromisos con sus límites presentes: probar algunos mecanismos no demuestra un método completamente inmune a las distracciones. El plan de dos minutos es una adaptación de ODA, no una dosis probada ni tratamiento para problemas de atención. Puedes tomar una decisión mejor informada y seguir teniendo un día difícil. Si los problemas persistentes afectan mucho tu vida, busca apoyo cualificado mientras continúas los experimentos cotidianos seguros y útiles; no necesitas fracasar en ellos antes de pedir ayuda."},fr:{hook:"Tu as ouvert le téléphone avant d’écrire la phrase difficile. Repère ce moment, puis choisis une réponse.",intro:"Eyal invite à examiner les conditions de la distraction, notamment les sensations pénibles, les sollicitations et la répartition du temps. ODA vérifie ces thèmes séparément: une explication convaincante ne prouve pas une méthode complète. Une action utile peut traiter une interruption ou un moment d’évitement sans exiger une attention parfaite. Le téléphone peut aussi servir à l’accessibilité, aux proches ou au travail; le but est un choix réaliste d’usage. Commence par une situation récurrente que tu peux modifier sans danger et par des informations observables. Une journée difficile ne suffit pas à conclure à un problème général de volonté.",ideas:[{id:"notice-discomfort",title:"Demande ce que le détour t’apportait",idea:"Eyal propose de regarder la sensation inconfortable qui peut précéder un éloignement du travail prévu. Lorsque tu cherches autre chose, demande-toi si tu ressentais ennui, incertitude, inquiétude ou manque de clarté, tout en gardant une place à la fatigue ordinaire et aux demandes légitimes. Tu peux reconnaître la sensation et choisir une réponse possible sans devoir te sentir bien d’abord ni traiter toute pause comme de l’évitement. Si la tâche est dangereuse ou la demande déraisonnable, repos, aide ou renégociation peuvent être plus adaptés qu’un retour à tout prix; identifie l’obstacle avant de lui donner une seule cause.",research:"Sirois et Pychyl envisagent la procrastination comme recherche d’un soulagement immédiat face aux sensations désagréables d’une tâche. C’est une explication utile pour certains retards, mais la source est une revue théorique narrative, pas un essai établissant une cause universelle de distraction. Elle ne montre ni qu’identifier une émotion suffit à changer la conduite, ni que toutes les barrières externes se règlent intérieurement. Le verdict est mitigé pour cette explication générale. Utilise la question pour repérer un obstacle possible, puis examine la réponse nécessaire, plutôt que d’attribuer d’avance le même mécanisme émotionnel à chaque détour.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Change les sollicitations qui t’écartent régulièrement",idea:"Le livre conseille d’examiner délibérément les sollicitations extérieures qui concurrencent l’action prévue, y compris la manière dont les appareils demandent de l’attention. Choisis un signal évitable et décide quand le consulter, sans supprimer tous les contacts ni promettre de ne jamais utiliser le téléphone. Une adaptation ODA est de mettre un groupe non essentiel en sourdine pendant une tâche et de fixer une consultation ultérieure, avec les contacts urgents disponibles. Si ton rôle exige une réponse rapide, discute d’une période protégée possible avec les personnes concernées au lieu de supposer que toute interruption dépend de toi.",research:"Dans une expérience à ordre contrebalancé auprès de 221 étudiants, une configuration du téléphone moins interruptive s’accompagnait de moins de symptômes déclarés d’inattention et d’hyperactivité. Les alertes et la visibilité ou proximité du téléphone changeaient ensemble, empêchant d’isoler la mise en sourdine comme cause. L’étude ne montre pas non plus que les téléphones causent le TDAH, traitent un problème clinique ou garantissent une productivité accrue. Le verdict est mitigé pour un réglage particulier, avec des données prometteuses pour le dispositif plus large. Essaie un changement sûr et regarde son effet observable sur ta tâche, sans considérer tous les usages comme également nuisibles.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Choisis la réponse avant le moment difficile",idea:"Eyal favorise une planification délibérée pour rendre clair l’usage souhaité d’une période lorsque les alternatives apparaissent. Repère une tâche que tu veux réellement poursuivre, le moment probable de diversion et une réponse faisable, y compris un geste plus petit ou une demande d’information. Comme adaptation ODA, si l’envie de vérifier les messages survient au début prévu d’écriture, écris d’abord la question non résolue dans le document, puis reconsidère la consultation au moment choisi. Le plan doit orienter une décision, pas devenir une règle rigide qui bloque la réponse à une urgence ou à un changement réel de situation.",research:"Les plans situation-réponse sont soutenus par la méta-analyse de Gollwitzer et Sheeran; une synthèse ultérieure a trouvé un bénéfice moyen modeste en associant repérage des obstacles et intentions de mise en œuvre. Ces travaux concernaient des objectifs variés et ne testaient pas toutes les règles de temps du livre. L’hétérogénéité et les indices de biais de publication limitent le bénéfice attendu de la seconde revue, et une phrase ODA n’est pas validée comme intervention complète. Le principe soutenu est une réponse faisable à une situation reconnaissable. Intègre les contraintes extérieures et juge la tentative réelle, pas seulement l’intention; une réponse attendue d’autrui n’est pas sous ton contrôle.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Rends l’engagement observable sans le rendre punitif",idea:"Le livre emploie des engagements pris à l’avance pour protéger des intentions, mais un engagement personnel doit rester sûr et proportionné. Choisis un relevé privé ou une vérification facultative indiquant si tu as essayé, sans dépenser, exposer des détails sensibles ou punir des interruptions inévitables. Si cela favorise la dissimulation ou l’autocritique, change le dispositif et cherche la barrière ignorée par la promesse initiale. L’engagement n’est utile que s’il aide à choisir ou à revoir; annoncer un plan ne prouve ni son exécution ni son adéquation actuelle, et la visibilité ne remplace pas l’exactitude.",research:"Les interventions de suivi ont amélioré en moyenne l’atteinte des objectifs dans les 138 études randomisées de la revue de Harkin et ses collègues. Les effets étaient plus grands avec un relevé matériel ou un partage, mais ces analyses n’établissent pas la causalité d’une promesse, d’un pacte ou d’une annonce précise. Les données de planification des obstacles portent aussi sur des programmes variés, pas sur tous les engagements possibles. Le verdict est mitigé pour un pacte particulier, avec un meilleur soutien au suivi exact. Garde le partage volontaire et le relevé honnête; une tentative manquée appelle une réponse plus faisable, pas une hausse du prix de l’échec.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"Prépare un plan pour une distraction en deux minutes",steps:["Nomme une tâche d’aujourd’hui et une distraction habituelle sans urgence.","Écris une réponse si-alors faisable et un autre moment pour consulter la distraction.","Modifie un signal sans danger, tout en conservant les contacts urgents et les outils d’accessibilité."],decision:"Aujourd’hui, j’écrirai une réponse à une distraction familière et je modifierai un signal sans danger."},takeaway:"Garde le plan de réponse précis. Utilise les explications émotionnelles, les réglages et les engagements avec leurs limites: des données sur certains mécanismes ne prouvent pas une méthode complètement imperméable à la distraction. Ce plan de deux minutes est une adaptation ODA, pas une dose testée ni un traitement de difficultés d’attention. Tu peux choisir de façon mieux informée et avoir quand même une journée difficile. Si des problèmes persistants affectent fortement ta vie, cherche du soutien qualifié tout en poursuivant les essais ordinaires sûrs et utiles; leur échec n’est pas un préalable pour demander de l’aide."},de:{hook:"Vor dem schwierigen Satz hast du das Handy geöffnet. Erkenne den Moment und wähle eine Antwort.",intro:"Eyal fordert dazu auf, die Bedingungen von Ablenkung zu prüfen, einschließlich unangenehmer Gefühle, eingehender Signale und der Zeitaufteilung. ODA untersucht diese Themen getrennt, denn eine überzeugende Erklärung beweist keine vollständige Methode. Eine nützliche Handlung kann eine Unterbrechung oder einen Vermeidungsmoment bearbeiten, ohne perfekte Aufmerksamkeit zu verlangen. Dein Telefon kann auch Hilfsmittel, Familienkontakt oder Arbeitsgerät sein; gesucht ist eine praktikable Entscheidung über seine Nutzung. Beginne mit einer wiederkehrenden Situation, die du sicher verändern kannst, und beobachtbaren Informationen. Ein schwieriger Tag ist kein ausreichender Grund für ein allgemeines Urteil über deine Disziplin oder alle Gewohnheiten mit Geräten.",ideas:[{id:"notice-discomfort",title:"Frage, was der Wechsel dir angeboten hat",idea:"Eyal regt an, das unangenehme Gefühl vor dem Abweichen von geplanter Arbeit zu untersuchen. Wenn du zu etwas anderem greifst, frage nach Langeweile, Unsicherheit, Anspannung oder einer unklaren Aufgabe und lass Platz für gewöhnliche Müdigkeit sowie berechtigte andere Anforderungen. Du kannst das Gefühl erkennen und eine machbare Antwort wählen, ohne dich zuerst gut fühlen oder jede Pause als Vermeidung einstufen zu müssen. Bei unsicheren Aufgaben oder überzogenen Forderungen kann die richtige Antwort Ruhe, Hilfe oder Neuverhandlung sein, statt um jeden Preis weiterzumachen; vor einer allgemeinen Erklärung solltest du das konkrete Hindernis kennen.",research:"Sirois und Pychyl betrachten Aufschieben als Suche nach kurzfristiger Erleichterung von unangenehmen Aufgabenemotionen. Das ist ein brauchbares Modell für manche Verzögerung, aber eine theoretische Übersicht und kein Versuch, der eine universelle Ursache aller Ablenkung feststellt. Sie zeigt weder, dass das Benennen eines Gefühls allein Verhalten verändert, noch dass äußere Hindernisse vollständig von innen gelöst werden können. Für die breite Erklärung ist der Befund gemischt. Nutze die Frage zur Suche nach einem möglichen Hindernis und prüfe dann die erforderliche Reaktion, statt jeder Abschweifung denselben Mechanismus zuzuschreiben. Unklare Ausführung und fehlende Mittel können andere Entscheidungen brauchen als ein unangenehmes Gefühl; deine Notiz ist keine Diagnose.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Verändere Signale, die dich wiederholt wegziehen",idea:"Das Buch empfiehlt, äußere Aufforderungen zur Aufmerksamkeit bewusst zu prüfen, auch die Gestaltung der Geräte. Wähle ein vermeidbares Signal und lege fest, wann du ihm begegnen willst, statt alle Kontaktwege abzuschaffen oder völligen Telefonverzicht zu versprechen. Eine ODA-Anpassung ist, eine nicht notwendige Gruppe für eine geplante Aufgabe stummzuschalten und später nachzusehen, während dringende Kontakte verfügbar bleiben. Erfordert deine Rolle schnelle Antworten, vereinbare eine realistische geschützte Phase mit den Betroffenen, statt anzunehmen, jede Unterbrechung sei kontrollierbar; dafür musst du vielleicht zuerst die tatsächlichen Erwartungen an die Reaktionszeit klären.",research:"In einem Experiment mit ausgeglichener Reihenfolge und 221 Studierenden ging eine weniger unterbrechende Telefonanordnung mit geringeren selbstberichteten Unaufmerksamkeits- und Hyperaktivitätssymptomen einher. Benachrichtigungen sowie Sichtbarkeit oder Reichweite des Telefons wurden gemeinsam verändert, sodass sich das Stummschalten nicht als einzelne Ursache isolieren lässt. Die Studie zeigt weder, dass Telefone ADHS verursachen, noch eine klinische Behandlung oder garantierte Produktivität. Für eine einzelne Einstellung ist das Urteil gemischt, für den umfassenderen Aufbau gibt es vielversprechende Befunde. Probiere eine sichere Änderung und prüfe die beobachtbare Wirkung auf deine Aufgabe, statt jede Nutzung gleich schädlich zu finden. Ein nicht gemessener Alltagserfolg darf nicht einfach aus den Symptomangaben abgeleitet werden.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Wähle die Antwort vor dem schwierigen Moment",idea:"Eyal bevorzugt bewusste Planung, damit die gewünschte Zeitnutzung klar ist, wenn Alternativen auftauchen. Wähle eine wirklich gewünschte Aufgabe, den wahrscheinlichen Ablenkungsmoment und eine dort mögliche Reaktion, einschließlich eines kleineren Schritts oder einer Nachfrage nach fehlenden Informationen. Als ODA-Anpassung kannst du beim Wunsch nach Nachrichten während eines geplanten Schreibbeginns zuerst die offene Frage im Dokument notieren und das Nachsehen zur gewählten Zeit neu entscheiden. Der Plan soll eine Entscheidung leiten und kein starres Gesetz werden, das Notfälle oder eine tatsächlich veränderte Lage ignoriert; nicht jede zukünftige Anforderung ist beim Aufschreiben bekannt.",research:"Hinweis-Reaktions-Pläne haben Unterstützung aus der Metaanalyse von Gollwitzer und Sheeran; eine spätere Übersicht fand einen bescheidenen durchschnittlichen Vorteil durch die Verbindung von Hindernisprüfung und Umsetzungsvorsätzen. Die Untersuchungen betrafen unterschiedliche Ziele und testeten nicht jede Zeitregel des Buchs. Unterschiedlichkeit und Hinweise auf Publikationsverzerrung begrenzen den erwartbaren Vorteil der späteren Analyse; ein kurzer ODA-Satz ist keine validierte Gesamtintervention. Gestützt wird eine machbare Antwort auf eine erkennbare Situation. Berücksichtige äußere Grenzen und beurteile den tatsächlichen Versuch statt nur die Absicht. Eine ausstehende Antwort anderer ist nicht deine eigene verfügbare Handlung; der Plan kann stattdessen festhalten, wie du die Information anfragst oder später prüfst.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Mach die Zusage sichtbar, ohne sie zur Strafe zu machen",idea:"Das Buch nutzt vorab eingegangene Verpflichtungen zum Schutz von Absichten, doch eine persönliche Zusage sollte sicher und verhältnismäßig bleiben. Wähle eine private Notiz oder freiwillige Rückfrage über den Versuch, ohne Geld auszugeben, sensible Details offenzulegen oder unvermeidbare Unterbrechungen zu bestrafen. Führt die Zusage zu Verschweigen oder Selbstkritik, ändere den Aufbau und frage, welche Grenze das ursprüngliche Versprechen übersehen hat. Sie ist nützlich, wenn sie eine Entscheidung oder deren Prüfung erleichtert; eine Ankündigung beweist weder Ausführung noch heutige Passung, deshalb sollte Sichtbarkeit nicht die Genauigkeit des Protokolls ersetzen.",research:"Fortschrittsbeobachtung verbesserte im Mittel die Zielerreichung in 138 randomisierten Studien der Übersicht von Harkin und seinem Team. Größere Effekte traten bei schriftlichem Festhalten oder Berichten auf, doch diese Analysen beweisen keinen kausalen Vorteil einer bestimmten Zusage, Vereinbarung oder öffentlichen Ankündigung. Auch die Hindernisplanungsforschung untersucht verschiedene Programme statt jeden Verpflichtungstyp. Für einen konkreten Pakt ist der Befund gemischt, für genaue Beobachtung stärker. Halte Teilen freiwillig und Notizen ehrlich; ein ausgelassener Versuch ist ein Anlass für eine machbare neue Antwort und keine Eskalation des Scheiterns. Wenn du eine Aufzeichnung lieber privat hältst, ist das keine schlechtere oder unvollständige Form des zulässigen persönlichen Experiments.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"Bereite in zwei Minuten einen Plan für eine Ablenkung vor",steps:["Benenne eine Aufgabe für heute und eine bekannte, nicht dringende Ablenkung.","Schreibe eine machbare Wenn-dann-Antwort und einen späteren Zeitpunkt zum Nachsehen auf.","Ändere ein Signal sicher, während Notfallkontakte und notwendige Hilfsmittel verfügbar bleiben."],decision:"Heute notiere ich eine Antwort auf eine bekannte Ablenkung und ändere ein Signal auf sichere Weise."},takeaway:"Behalte den konkreten Reaktionsplan. Nutze Gefühlserklärungen, Geräteeinstellungen und Zusagen mit ihren Grenzen, denn Befunde zu einzelnen Mechanismen beweisen keine vollständig ablenkungssichere Methode. Der Zweiminutenplan ist eine ODA-Anpassung, keine getestete Dosis und keine Behandlung von Aufmerksamkeitsproblemen. Du kannst besser informiert entscheiden und trotzdem einen schwierigen Tag haben. Beeinträchtigen anhaltende Probleme dein Leben deutlich, hole qualifizierte Unterstützung, während du sichere Alltagsexperimente fortsetzt. Deren Scheitern ist keine Voraussetzung für Hilfe; ein ehrlicher Verlauf soll Informationen liefern und dich nicht dazu verpflichten, alle Schwierigkeiten allein zu lösen."},it:{hook:"Hai aperto il telefono prima della frase difficile. Nota quel momento e scegli una risposta.",intro:"Eyal invita a esaminare le condizioni della distrazione, comprese sensazioni sgradevoli, richiami esterni e distribuzione del tempo. ODA controlla questi temi separatamente: una spiegazione convincente non prova un metodo intero. Un’azione utile può affrontare un’interruzione o un momento di evitamento senza chiedere attenzione perfetta. Il telefono può essere uno strumento di accessibilità, un contatto familiare o parte del lavoro; cerchiamo una scelta praticabile sul suo uso. Parti da una situazione ricorrente che puoi cambiare in sicurezza e da informazioni osservabili. Una giornata difficile non basta a giudicare la tua disciplina o tutte le abitudini con i dispositivi.",ideas:[{id:"notice-discomfort",title:"Chiediti cosa offriva il cambio di attività",idea:"Eyal suggerisce di esaminare il disagio che può precedere l’allontanamento dal lavoro previsto. Quando cerchi altro, chiediti se eri annoiato, incerto, preoccupato o davanti a un compito poco chiaro, lasciando spazio a normale stanchezza e richieste legittime. Puoi riconoscere la sensazione e scegliere una risposta possibile senza dover stare bene prima né classificare ogni pausa come evitamento. Se il compito è rischioso o la richiesta irragionevole, riposo, aiuto o rinegoziazione possono essere più adatti di un ritorno a ogni costo; identifica l’ostacolo concreto prima di scegliere una spiegazione unica per tutte le interruzioni.",research:"Sirois e Pychyl descrivono la procrastinazione come ricerca di sollievo immediato dalle sensazioni spiacevoli di un compito. È una spiegazione utile per alcuni rinvii, ma una rassegna teorica narrativa, non un esperimento che stabilisce una causa universale della distrazione. Non dimostra che nominare un’emozione cambi da solo il comportamento né che tutte le barriere esterne siano gestibili dall’interno. Il giudizio sulla spiegazione generale è misto. Usa la domanda per individuare un possibile ostacolo e poi valuta la risposta necessaria, anziché attribuire a ogni deviazione lo stesso meccanismo. Un compito poco chiaro e una risorsa mancante possono richiedere scelte differenti da una sensazione spiacevole; il tuo appunto non è una diagnosi.",verdict:"mixed",sourceIds:["mood-repair"]},{id:"selective-interruptions",title:"Modifica i richiami che ti portano via ripetutamente",idea:"Il libro raccomanda di esaminare deliberatamente i segnali esterni che competono con l’azione desiderata, compreso il modo in cui i dispositivi chiedono attenzione. Scegli un richiamo evitabile e decidi quando incontrarlo, invece di eliminare tutti i contatti o promettere di non usare mai il telefono. Un adattamento ODA è silenziare un gruppo non essenziale durante un compito e scegliere un controllo successivo, mantenendo disponibili i contatti urgenti. Se il ruolo richiede risposte rapide, concorda un periodo protetto fattibile con le persone coinvolte, invece di presumere che ogni interruzione dipenda da te; potrebbe prima servire chiarezza sulle aspettative reali di risposta.",research:"In un esperimento con ordine controbilanciato e 221 universitari, un assetto del telefono meno interruttivo si accompagnava a minori sintomi riferiti di disattenzione e iperattività. Cambiavano insieme notifiche e visibilità o vicinanza del dispositivo, quindi non si può isolare il silenziamento come causa. Lo studio non dimostra che il telefono causi DDAI, tratti un problema clinico o garantisca più produttività. Il giudizio per una specifica impostazione è misto, con prove promettenti per il dispositivo complessivo. Prova una modifica sicura e valuta l’effetto osservabile sul compito, senza considerare tutti gli usi ugualmente dannosi. Un beneficio quotidiano non misurato non va dedotto automaticamente dai sintomi autoriportati.",verdict:"mixed",sourceIds:["phone-notifications"]},{id:"prepared-response",title:"Scegli la risposta prima del momento difficile",idea:"Eyal favorisce la pianificazione deliberata, perché l’uso desiderato di un periodo sia chiaro quando compaiono alternative. Individua un compito che vuoi davvero affrontare, il momento probabile della deviazione e una risposta possibile, compreso un passo minore o una richiesta di informazioni. Come adattamento ODA, se senti l’impulso di leggere messaggi all’inizio previsto della scrittura, annota prima la domanda irrisolta nel documento e rivaluta il controllo all’orario scelto. Il piano deve guidare una scelta, non diventare una regola rigida che impedisce di rispondere a un’emergenza o a circostanze realmente cambiate, che non potevi conoscere tutte quando lo hai scritto.",research:"I piani segnale-risposta hanno sostegno dalla meta-analisi di Gollwitzer e Sheeran; una sintesi successiva ha trovato un beneficio medio modesto associando identificazione degli ostacoli e intenzioni di attuazione. Gli studi riguardavano obiettivi vari e non provavano ogni regola di tempo del libro. Eterogeneità e segnali di distorsione di pubblicazione limitano il beneficio atteso dalla revisione successiva; una breve frase ODA non è convalidata come intervento completo. Il principio sostenuto è preparare una risposta fattibile a una situazione riconoscibile. Includi vincoli esterni reali e giudica il tentativo, non solo l’intenzione; una risposta che aspetti da altri non è un’azione disponibile sotto il tuo controllo.",verdict:"supported",sourceIds:["if-then-plans","obstacle-planning"]},{id:"voluntary-commitment",title:"Rendi osservabile l’impegno senza renderlo punitivo",idea:"Il libro usa impegni anticipati per proteggere intenzioni, ma un impegno personale deve restare sicuro e proporzionato. Scegli una registrazione privata o un controllo facoltativo del tentativo, senza spendere, esporre dettagli sensibili o punire interruzioni inevitabili. Se favorisce occultamento o autocritica, modifica il progetto e cerca la barriera trascurata dalla promessa iniziale. L’impegno è utile se aiuta a scegliere o rivedere; annunciare un piano non prova che tu l’abbia seguito né che sia ancora adatto, quindi visibilità ed esattezza del resoconto non sono la stessa cosa.",research:"Gli interventi di monitoraggio miglioravano mediamente il raggiungimento degli obiettivi nei 138 studi randomizzati della revisione di Harkin e colleghi. Gli effetti erano maggiori con registrazione materiale o comunicazione, ma questi confronti non stabiliscono il vantaggio causale di una specifica promessa, patto o annuncio pubblico. Anche le prove sulla pianificazione degli ostacoli riguardano programmi diversi, non ogni formato di impegno. Il giudizio su un patto concreto è misto, con sostegno maggiore per un monitoraggio preciso. Mantieni volontaria la condivisione e sincera la registrazione; un tentativo mancato invita a rivedere la risposta possibile, non ad aumentare il costo del fallimento. Tenere privata la nota è comunque un’opzione completa per il tuo esperimento.",verdict:"mixed",sourceIds:["progress-monitoring","obstacle-planning"]}],action:{title:"Prepara un piano per una distrazione in due minuti",steps:["Nomina un compito di oggi e una distrazione ricorrente che non sia urgente.","Scrivi una risposta se-allora fattibile e un momento successivo per controllare la distrazione.","Modifica un segnale in sicurezza, mantenendo contatti urgenti e strumenti di accessibilità."],decision:"Oggi scriverò una risposta a una distrazione abituale e modificherò un segnale in modo sicuro."},takeaway:"Conserva il piano di risposta specifico. Usa spiegazioni emotive, impostazioni e impegni tenendo presenti i limiti: le prove su alcuni meccanismi non dimostrano un metodo completamente immune alla distrazione. Il piano di due minuti è un adattamento ODA, non una dose studiata o un trattamento per difficoltà di attenzione. Puoi scegliere con più informazioni e avere comunque una giornata dura. Se problemi persistenti compromettono molto la vita, cerca sostegno qualificato mentre continui esperimenti quotidiani sicuri e utili. Non devi prima fallire questi tentativi: un resoconto sincero offre informazioni, non ti obbliga a risolvere da solo ogni difficoltà."}}};export{e as default};
